// CopiedFormat is the package's CopiedFormat in the language of msgs.
func (msgs Messages) CopiedFormat(format string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.CopiedFormat(format))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].CopiedFormat; f != nil {
			return f(format)
		}
		switch lang {
		case "", "en":
			return msgs.arg(format) + " copied"
		case "zh-Hans":
			return format + " 已复制"
		case "zh-Hant":
			return format + " 已複製"
		}
	}
}

