// in the language the app shows under cx.
func RecentCount(cx *core.Scope, count int) string { return For(cx).RecentCount(count) }

// RecentCount is the package's RecentCount in the language of msgs.
func (msgs Messages) RecentCount(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.RecentCount(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].RecentCount; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			return "Recent " + msgs.arg(i18n.FormatNumber("en", float64(count))) + " / 20"
		case "zh-Hans":
			return "最近 " + i18n.FormatNumber("zh-Hans", float64(count)) + " / 20"
		case "zh-Hant":
			return "最近 " + i18n.FormatNumber("zh-Hant", float64(count)) + " / 20"
		}
	}
}

